const $ = (s,el=document)=>el.querySelector(s);
const $$ = (s,el=document)=>[...el.querySelectorAll(s)];
// 텍스트·속성 컨텍스트 모두 안전하도록 따옴표까지 이스케이프(외부 G2B 문자열이 속성에 들어가는 경우 대비)
const esc = s => String(s==null?'':s)
  .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
  .replace(/"/g,'&quot;').replace(/'/g,'&#39;');
// href 용 URL 새니타이즈: http(s) 만 허용, 그 외(javascript: 등)는 무력화
const safeUrl = u => { const s=String(u==null?'':u).trim();
  return /^https?:\/\//i.test(s) ? s : ''; };

// 소개 페이지 등장 애니메이션: 스크롤 진입 시 reveal + 숫자 카운트업. reduced-motion 이면 즉시 확정.
function lpAnimate(){
  const root=$('#view'); if(!root) return;
  const reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if(reduce){
    $$('.reveal,.lp-rise',root).forEach(el=>{ el.classList.add('in'); el.style.opacity=''; el.style.animation='none'; el.style.transform='none'; });
    $$('[data-count]',root).forEach(el=>{ el.textContent=el.dataset.count+(el.dataset.suffix||''); });
    return;
  }
  if(!('IntersectionObserver' in window)){ $$('.reveal,.lp-counts',root).forEach(el=>el.classList.add('in')); return; }
  const io=new IntersectionObserver(es=>{ es.forEach(e=>{ if(e.isIntersecting){
    e.target.classList.add('in');
    if(e.target.classList.contains('lp-counts')) $$('[data-count]',e.target).forEach(countUp);
    io.unobserve(e.target); } }); }, {threshold:.18, rootMargin:'0px 0px -8% 0px'});
  $$('.reveal,.lp-counts',root).forEach(el=>io.observe(el));
}
function countUp(el){ if(el._done) return; el._done=true;
  const target=parseInt(el.dataset.count,10)||0, suffix=el.dataset.suffix||'';
  const dur=1100, t0=performance.now(), fmt=n=>String(n)+suffix;
  (function tick(now){ const p=Math.min(1,(now-t0)/dur), e=1-Math.pow(1-p,3);
    el.textContent=fmt(Math.round(target*e)); if(p<1) requestAnimationFrame(tick); })(t0);
}

// pywebview API 준비 대기
function api(){ return (window.pywebview && window.pywebview.api) || null; }
function waitApi(){ return new Promise(res=>{
  if(api()) return res(api());
  window.addEventListener('pywebviewready', ()=>res(api()), {once:true});
  // 폴백: 폴링
  let t=setInterval(()=>{ if(api()){clearInterval(t);res(api());} }, 80);
}); }

