/* ---------- 토스트 ---------- */
function attachClearButtons(scope){
  scope=scope||document;
  var ins=scope.querySelectorAll('input.input.has-clear, input[data-clear]');
  // fallback: 검색용 input 자동 인식(id 가 -q 로 끝나거나 placeholder 에 검색)
  var all=scope.querySelectorAll('input.input');
  var list=[];
  for(var k=0;k<all.length;k++){ var el=all[k];
    var idok=(el.id||'').slice(-2)==='-q';
    var phok=((el.getAttribute('placeholder')||'').indexOf('검색')>=0);
    if(idok||phok){ list.push(el); } }
  for(var j=0;j<list.length;j++){ (function(input){
    if(input.__clearBound){ return; } input.__clearBound=true;
    var wrap=document.createElement('span'); wrap.className='clearwrap';
    var st=input.getAttribute('style')||''; 
    if(st.indexOf('flex')>=0){ wrap.style.flex='1'; input.style.flex='1'; }
    input.parentNode.insertBefore(wrap, input);
    wrap.appendChild(input);
    var btn=document.createElement('button'); btn.type='button'; btn.className='clearbtn';
    btn.setAttribute('aria-label','검색어 지우기'); btn.title='지우기'; btn.textContent='\u00d7';
    wrap.appendChild(btn);
    function sync(){ btn.style.display = input.value ? 'flex' : 'none'; }
    sync();
    input.addEventListener('input', sync);
    btn.addEventListener('mousedown', function(e){ e.preventDefault(); });
    btn.addEventListener('click', function(){ input.value=''; sync();
      input.dispatchEvent(new Event('input',{bubbles:true})); input.focus(); });
  })(list[j]); }
}

function __initClearObserver(){
  var v=document.getElementById('view')||document.body;
  attachClearButtons(document);
  try{ var mo=new MutationObserver(function(){ attachClearButtons(document); });
    mo.observe(v,{childList:true,subtree:true}); }catch(e){}
}
if(document.readyState!=='loading'){ __initClearObserver(); }
else{ document.addEventListener('DOMContentLoaded', __initClearObserver); }
function toast(title, body, kind){
  const el=document.createElement('div');
  el.className='toast'+(kind?(' toast--'+kind):'');
  el.setAttribute('role', kind==='danger'?'alert':'status');
  el.innerHTML=`<div style="flex:1"><div class="toast__title">${esc(title)}</div>${body?`<div class="toast__body">${esc(body)}</div>`:''}</div><button class="toast__x" aria-label="닫기">×</button>`;
  $('#toasts').appendChild(el);
  $('.toast__x',el).onclick=()=>el.remove();
  // 모든 토스트 자동 사라짐(실패 알림도). 실패는 조금 더 오래(6초) 보여줌.
  setTimeout(()=>el.remove(), kind==='danger'?6000:4000);
}

/* ---------- 모달 ---------- */
function modal({title, body, okText='확인', cancelText='취소', danger=false, onOk}){
  const root=$('#modal-root');
  const prevFocus=document.activeElement;   // 닫은 뒤 포커스를 되돌릴 원래 요소
  root.innerHTML=`<div class="modal-overlay"><div class="modal" role="dialog" aria-modal="true">
    <div class="modal__head"><h2>${esc(title)}</h2></div>
    <div class="modal__body">${body}</div>
    <div class="modal__foot">
      <button class="btn btn--ghost" id="m-cancel">${esc(cancelText)}</button>
      <button class="btn ${danger?'btn--danger':'btn--primary'}" id="m-ok">${esc(okText)}</button>
    </div></div></div>`;
  const dialog=$('.modal',root);
  const close=()=>{ root.innerHTML='';
    document.removeEventListener('keydown', onKey, true);
    if(prevFocus && prevFocus.focus) try{ prevFocus.focus(); }catch(e){} };
  // 포커스 트랩 + Escape: Tab 이 모달 안에서만 순환하도록 가둔다
  function onKey(e){
    if(e.key==='Escape'){ e.preventDefault(); close(); return; }
    if(e.key!=='Tab') return;
    const items=$$('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])', dialog)
      .filter(el=>!el.disabled && el.offsetParent!==null);
    if(!items.length) return;
    const first=items[0], last=items[items.length-1];
    if(e.shiftKey && document.activeElement===first){ e.preventDefault(); last.focus(); }
    else if(!e.shiftKey && document.activeElement===last){ e.preventDefault(); first.focus(); }
  }
  document.addEventListener('keydown', onKey, true);
  $('#m-cancel').onclick=close;
  $('.modal-overlay').onclick=e=>{ if(e.target.classList.contains('modal-overlay')) close(); };
  $('#m-ok').onclick=async()=>{ if(onOk){ const r=await onOk(); if(r===false) return; } close(); };
  $('#m-ok').focus();
}

