/* ---------- 연동 설정 바인딩 (자동 저장) — connect() 화면 전용 ---------- */
function bindSettings(scope=document){
  // 비밀 보기/숨기기 토글 (텍스트 라벨 버튼)
  $$('[data-eye]',scope).forEach(b=>b.onclick=()=>{ const f=$('#'+b.dataset.eye);
    const show = f.type==='password'; f.type = show?'text':'password';
    b.setAttribute('aria-pressed', show?'true':'false'); });

  // 대화 ID(평문 텍스트) → blur 시 자동 저장
  { const el=$('#f-chat',scope);
    if(el) el.addEventListener('change',()=>autoSave({telegram_chat_id:el.value.trim()})); }

  // 비밀(서비스키/봇토큰): 값 입력 후 blur 시에만 저장(빈값이면 기존 유지)
  ['f-g2b','f-bot'].forEach(id=>{ const el=$('#'+id,scope); if(!el) return;
    el.addEventListener('change',()=>{ const v=el.value.trim(); if(!v) return;
      autoSave(id==='f-g2b'?{g2b_service_key:v}:{telegram_bot_token:v}); }); });

  // 대화 ID 자동 찾기
  const findChat=$('#s-findchat',scope);
  if(findChat) findChat.onclick=async(e)=>{
    modal({title:'대화 ID 찾기', okText:'찾기', cancelText:'닫기',
      body:'먼저 텔레그램에서 만드신 봇에게 아무 메시지(예: /start)나 한 번 보내 주세요.<br>보내셨다면 [찾기]를 눌러 주세요.',
      onOk:async()=>{ const r=await api().find_chat_id($('#f-bot').value.trim());
        if(r.ok){ $('#f-chat').value=r.chat_id; autoSave({telegram_chat_id:r.chat_id});
          toast('찾았습니다', '대화 ID: '+r.chat_id,'success'); }
        else { toast('찾지 못했습니다', r.error,'danger'); return false; } }});
  };
  // 테스트 메시지
  const testTg=$('#s-testtg',scope);
  if(testTg) testTg.onclick=e=>doTest(e.currentTarget);
}

/* ---------- 공통 설정 바인딩 (자동 저장) — filters() 화면: 지역/면허/업무구분 ---------- */
function bindCommonSettings(scope=document){
  // 면허: 검색형 위젯(자동저장).
  bindLicense(scope, ()=>autoSave({licenses:readTags(document,'licenses')}));
  // 지역: 단일 선택 검색형 드롭다운(자동저장).
  bindRegion(scope, (v)=>autoSave({region:(v||'').trim()}));

  // 업무구분 체크 → 즉시 저장(최소 1개)
  $$('#f-divs .check',scope).forEach(l=>{ const inp=l.querySelector('input');
    inp.onchange=()=>{ l.classList.toggle('on',inp.checked);
      const divs=$$('#f-divs input:checked').map(i=>i.value);
      if(divs.length) autoSave({work_divs:divs});
      else { inp.checked=true; l.classList.add('on'); toast('확인','업무 구분은 최소 하나가 필요합니다.','danger'); } }; });
  bindPeriodField(scope);   // 공고일자 수집 기간(수집 대상 카드)
}

/* ---------- 알림 설정 바인딩 (자동 저장) — notify() 화면 ---------- */
function bindNotifySettings(scope=document){
  const textMap={ 'f-company':'company_nm', 'f-max':'max_per_run' };
  Object.entries(textMap).forEach(([id,key])=>{ const el=$('#'+id,scope); if(!el) return;
    el.addEventListener('change',()=>{ let v=el.value.trim();
      if(el.type==='number') v=+v; autoSave({[key]:v}); }); });
  const tgl={ 'f-unknown':'include_unknown', 'f-brief':'include_briefing' };
  Object.entries(tgl).forEach(([id,key])=>{ const el=$('#'+id,scope); if(!el) return;
    el.addEventListener('change',()=>autoSave({[key]:el.checked})); });
}

/* ---------- 공고일자 수집 기간 (1주 단위) ----------
   나라장터 목록 API 는 한 번 조회에 '최대 1개월'까지 허용 → 1주 단위로 고르게 함.
   1주/2주/3주/1개월 모두 1개월 이내라 단일 호출로 처리(분할 불필요). 기본은 1주. */
const PERIOD_OPTS=[
  {v:'1w',t:'최근 1주'},
  {v:'2w',t:'최근 2주'},
  {v:'3w',t:'최근 3주'},
  {v:'1m',t:'최근 1개월'},
];
const PERIOD_VALID=new Set(PERIOD_OPTS.map(o=>o.v));
function periodFieldHtml(c){
  let mode=(c&&c.period_mode)||'1w';
  if(!PERIOD_VALID.has(mode)) mode='1w';   // 옛 3m/6m/range 저장값이면 1주로 표시
  return `<div class="field" id="period-field">
    <label class="field__label">공고일자 (수집 기간)</label>
    <div class="seg" id="f-period-seg" role="group" aria-label="수집 기간 선택">
      ${PERIOD_OPTS.map(o=>`<button type="button" class="seg__btn ${mode===o.v?'on':''}" data-pm="${o.v}" aria-pressed="${mode===o.v}">${o.t}</button>`).join('')}
    </div>
    <div class="field__help">선택한 기간에 <b>올라온 공고</b>를 빠짐없이 수집합니다. 짧게 잡으면 가볍고 빠르며, <b>최근 1개월</b>까지 한 번에 받을 수 있습니다(나라장터가 한 번에 제공하는 최대 범위).</div>
  </div>`;
}
function bindPeriodField(scope=document){
  const seg=$('#f-period-seg',scope); if(!seg) return;
  seg.querySelectorAll('.seg__btn').forEach(b=>b.addEventListener('click',()=>{
    const pm=b.dataset.pm;
    seg.querySelectorAll('.seg__btn').forEach(x=>{ const on=x===b; x.classList.toggle('on',on); x.setAttribute('aria-pressed',on); });
    autoSave({period_mode:pm});
  }));
}

/* ---------- 수집 조건 프리셋 영역 (탭 + 8필드, CRUD) ---------- */
function presetList(){ return (STATE.cfg&&STATE.cfg.presets)||[]; }

function activePreset(){
  const ps=presetList(); if(!ps.length) return null;
  let p=ps.find(x=>x.id===STATE.activePreset);
  if(!p){ p=ps[0]; STATE.activePreset=p.id; }
  return p;
}

let _presetTimer=null;
// 선택 프리셋 저장(디바운스). collectWizardFields 로 8필드 머지(화면에 없는 필드는 저장값 유지)
// → 마법사처럼 일부 필드만 DOM에 있어도 나머지를 빈값으로 덮어쓰지 않음. 카드 화면은 전 필드 DOM 존재라 동일.
async function flushPresetSave(){
  const p=activePreset(); if(!p) return;
  const payload=collectWizardFields();
  try{ const r=await api().save_preset(payload);
    if(r.ok){ STATE.cfg.presets=r.presets; STATE.activePreset=r.preset_id; showSaved(); await refreshStatus(); updatePresetWarn(); }
    else toast('저장 실패', r.error,'danger');
  }catch(e){ toast('저장 오류','잠시 후 다시 시도해 주세요.','danger'); }
}
function savePresetDebounced(){
  const p=activePreset(); if(!p) return;
  clearTimeout(_presetTimer);
  _presetTimer=setTimeout(flushPresetSave, 500);
}

// 켜진 프리셋이 0개면 경고(수집 안 됨). 8필드 저장 직후 갱신.
function updatePresetWarn(){
  const warn=$('#preset-warn'); if(!warn) return;
  const onCnt=presetList().filter(p=>p.enabled).length;
  warn.style.display = onCnt? 'none':'flex';
}

function renderPresetArea(){
  const area=$('#preset-area'); if(!area) return;
  const ps=presetList(); const p=activePreset();
  const c=STATE.cfg||{};
  if(!p){ area.innerHTML='<div class="field__help">수집 조건을 불러오지 못했습니다.</div>'; return; }
  // 단일 조건일 때는 사용/안함 토글을 숨기므로(끄면 수집 0건), 꺼져 있으면 자동으로 켜 안전 보정.
  if(ps.length===1 && !p.enabled){ p.enabled=true; try{ api().toggle_preset(p.id, true); }catch(e){} }
  const kw=(p.keywords&&!Array.isArray(p.keywords))?p.keywords
            :{include:Array.isArray(p.keywords)?p.keywords:[],all:[],exclude:[]};
  // 탭: 2개 이상일 때만 노출(점진적 노출). 켜짐=또렷한 색(.on), 꺼짐=흐림(.off)
  const tabs = ps.length>1 ? `<div class="preset-tabs" id="preset-tabs">${
      ps.map(x=>`<button class="preset-tab ${x.id===p.id?'active':''} ${x.enabled?'on':'off'}" data-pid="${esc(x.id)}" title="${x.enabled?'사용 중':'사용 안 함'}">
        <span class="preset-tab__dot"></span>${esc(x.name)}</button>`).join('')
    }</div>` : '';
  area.innerHTML = `
    ${tabs}
    <div class="preset-body">
      ${ps.length>1 ? `<div class="preset-head">
        <label class="switch switch--sm preset-toggle ${p.enabled?'is-on':'is-off'}" title="이 수집 조건 사용 여부">
          <input type="checkbox" id="preset-enabled" ${p.enabled?'checked':''}>
          <span class="switch__track"><span class="switch__knob"></span></span>
          <span class="preset-toggle__label">${p.enabled?'사용 중':'사용 안 함'}</span></label>
        <input class="input preset-name" id="preset-name" value="${esc(p.name)}" placeholder="수집 조건 이름(예: 청소 용역)">
        <button class="iconbtn iconbtn--archive" id="preset-del" title="이 수집 조건 삭제"><svg viewBox="0 0 24 24" width="17" height="17"><use href="#ic-trash"/></svg></button>
      </div>`
      : `<input type="hidden" id="preset-enabled" checked><input type="hidden" id="preset-name" value="${esc(p.name)}">`}

      <div class="field kw-3">
        <label class="field__label">관심 키워드 <span class="badge badge--gold">수집량 결정</span></label>
        <div class="field__help" style="margin:-2px 0 10px">공고명을 기준으로 어떤 공고를 수집할지 결정합니다. 모두 비우면 ‘수집 대상’의 모든 공고를 수집합니다.</div>
        <div class="kw-grid">
          <div class="field kw-box"><label class="field__label"><span class="kw-dot kw-dot--inc"></span>포함 <span class="kw-tag-desc">이 중 하나라도</span></label>
            ${tagInput('kw-include', kw.include, '예: 청소, 시설관리, 전기공사')}
            <div class="field__help">하나라도 공고명에 들어가면 수집합니다.</div></div>
          <div class="field kw-box"><label class="field__label"><span class="kw-dot kw-dot--all"></span>필수 <span class="kw-tag-desc">모두 들어가야</span></label>
            ${tagInput('kw-all', kw.all, '예: 용역')}
            <div class="field__help">입력한 단어가 <b>모두</b> 포함된 공고만 수집합니다.</div></div>
          <div class="field kw-box"><label class="field__label"><span class="kw-dot kw-dot--exc"></span>제외 <span class="kw-tag-desc">있으면 제외</span></label>
            ${tagInput('kw-exclude', kw.exclude, '예: 교육, 채용')}
            <div class="field__help">이 단어가 들어간 공고는 제외합니다.</div></div>
        </div>
        <div class="field__help" style="margin-top:6px">예) 포함 <b>청소·시설관리·전기공사</b>, 필수 <b>용역</b>, 제외 <b>교육</b> → “셋 중 하나가 있고, 용역이 반드시 들어가며, 교육은 없는” 공고만 수집합니다.</div>
      </div>

      <div class="field"><label class="field__label">계약방법 <span class="muted small">(비우면 전체)</span></label>
        <div class="checks" id="f-cntrct">${(c.cntrct_mthd_options||['일반경쟁','제한경쟁','지명경쟁','수의계약']).map(m=>{
          const on=(p.cntrct_mthds||[]).includes(m);
          return `<label class="check ${on?'on':''}"><input type="checkbox" value="${esc(m)}" ${on?'checked':''}>${esc(m)}</label>`;
        }).join('')}</div>
        <div class="field__help">선택한 계약방법의 공고만 수집합니다. 예: 제한경쟁만 받기.</div></div>

      <div class="field"><label class="field__label">추정가격 하한 <span class="muted small">(이 금액 이상만 · 비우면 제한 없음)</span></label>
        <div class="price-min">
          <input class="input num" id="f-price-floor" inputmode="numeric" placeholder="예: 20,000,000" value="${p.price_floor?Number(p.price_floor).toLocaleString():''}">
          <span class="price-min__unit">원 이상</span>
          <span class="price-min__ko ${p.price_floor?'':'empty'}" id="f-price-floor-ko">${p.price_floor?wonKo(p.price_floor)+' 이상':'제한 없음'}</span>
        </div>
        <div class="field__help">설정한 금액보다 추정가격이 낮은 소액 공고는 제외됩니다. 비워 두면 금액 제한 없이 모두 수집합니다.</div></div>

      <div class="field"><label class="field__label">발주처 지정 <span class="muted small">(비우면 전체 발주처)</span></label>
        ${tagInput('f-org', p.org_includes, '예: 교육청, 시청, 구청')}
        <div class="field__help">입력한 이름이 발주처·공고기관에 포함된 공고만 수집합니다(부분일치, 여럿이면 하나라도 맞으면).</div></div>

      <div class="field"><label class="field__label">용역 세부분류 <span class="muted small">(용역에만 적용 · 비우면 전체)</span></label>
        <div class="checks" id="f-srvce">${(c.srvce_div_options||['일반용역','기술용역']).map(s=>{
          const on=(p.srvce_divs||[]).includes(s);
          return `<label class="check ${on?'on':''}"><input type="checkbox" value="${esc(s)}" ${on?'checked':''}>${esc(s)}</label>`;
        }).join('')}</div>
        <div class="field__help">업무 구분에서 ‘용역’을 받을 때, 일반용역/기술용역만 추려 받습니다. 물품·공사에는 영향 없습니다.</div></div>

      <div class="field"><label class="field__label">재공고 처리</label>
        <div class="checks" id="f-rentce">
          <label class="check ${(p.re_ntce_mode||'include')==='include'?'on':''}"><input type="radio" name="f-rentce" value="include" ${(p.re_ntce_mode||'include')==='include'?'checked':''}>포함</label>
          <label class="check ${p.re_ntce_mode==='exclude'?'on':''}"><input type="radio" name="f-rentce" value="exclude" ${p.re_ntce_mode==='exclude'?'checked':''}>제외</label>
          <label class="check ${p.re_ntce_mode==='only'?'on':''}"><input type="radio" name="f-rentce" value="only" ${p.re_ntce_mode==='only'?'checked':''}>재공고만</label>
        </div>
        <div class="field__help">재공고 = 한 번 유찰 등으로 다시 올라온 공고. 보통 ‘포함’이 안전합니다.</div></div>
    </div>
    <div class="card--note preset-warn" id="preset-warn" style="margin-top:14px;display:none">
      <svg viewBox="0 0 24 24" width="18" height="18" style="flex:0 0 auto;color:var(--warning,#C77700)"><use href="#ic-x"/></svg>
      <div>켜진 수집 조건이 없습니다. 최소 하나를 켜야 공고를 수집합니다.</div></div>`;
  updatePresetWarn();
  bindPresetFields();
}

// 프리셋 8필드 + 탭/추가/삭제/토글/이름 바인딩
function bindPresetFields(scope=document){
  const p=activePreset(); if(!p) return;

  // 탭 전환
  $$('#preset-tabs .preset-tab',scope).forEach(b=>b.onclick=()=>{
    STATE.activePreset=b.dataset.pid; renderPresetArea(); });

  // 조건 추가 → 빈 프리셋 생성 후 마법사(add 모드)로 안내
  const addBtn=$('#preset-add');   // 카드 헤더에 있음(area 밖)
  if(addBtn) addBtn.onclick=async()=>{
    const n=presetList().length+1;
    // 새 수집 조건은 추정가 제한 없이(전량) 시작. 소액을 거르려면 고객이 하한을 직접 입력.
    const r=await api().save_preset({name:`수집 조건 ${n}`});
    if(r.ok){ STATE.cfg.presets=r.presets; STATE.activePreset=r.preset_id;
      await refreshStatus();
      STATE.wizard.step=1; STATE.wizard.mode='add'; go('wizard'); }
    else toast('추가 실패', r.error,'danger');
  };

  // on/off 토글
  const en=$('#preset-enabled',scope);
  if(en) en.onchange=async()=>{
    const r=await api().toggle_preset(p.id, en.checked);
    if(r.ok){ STATE.cfg.presets=r.presets; renderPresetArea(); showSaved(); await refreshStatus(); }
    else { en.checked=!en.checked; toast('변경 실패', r.error,'danger'); }
  };

  // 이름 변경(blur 저장 — 빈값이면 되돌림)
  const nameEl=$('#preset-name',scope);
  if(nameEl) nameEl.addEventListener('change',async()=>{
    const v=nameEl.value.trim();
    if(!v){ nameEl.value=p.name; toast('확인','수집 조건 이름을 입력해 주세요.','danger'); return; }
    if(v===p.name) return;
    const r=await api().save_preset({id:p.id, name:v});
    if(r.ok){ STATE.cfg.presets=r.presets; const np=presetList().find(x=>x.id===p.id); if(np) p.name=np.name;
      renderPresetArea(); showSaved(); await refreshStatus(); }
    else { nameEl.value=p.name; toast('변경 실패', r.error,'danger'); }
  });

  // 삭제(최소 1개 유지 — 백엔드 가드 + 확인 모달)
  const delBtn=$('#preset-del',scope);
  if(delBtn && !delBtn.disabled) delBtn.onclick=()=>{
    modal({title:'수집 조건 삭제', danger:true,
      body:`수집 조건 <b>‘${esc(p.name)}’</b>을(를) 삭제합니다. 되돌릴 수 없습니다. 계속할까요?`,
      okText:'삭제', onOk:async()=>{ const r=await api().delete_preset(p.id);
        if(r.ok){ STATE.cfg.presets=r.presets; STATE.activePreset=(r.presets[0]||{}).id||null;
          renderPresetArea(); showSaved(); await refreshStatus(); }
        else { toast('삭제 실패', r.error,'danger'); return false; } }});
  };

  // 조건 초기화(이 프리셋의 8필드 비우기 — 이름·on/off 는 유지)
  const resetBtn=$('#preset-reset',scope);
  if(resetBtn) resetBtn.onclick=()=>{
    modal({title:'조건 초기화',
      body:`수집 조건 <b>‘${esc(p.name)}’</b>의 키워드·가격·계약방법 등 입력을 모두 비웁니다. 이름과 사용 여부는 그대로 둡니다. 계속할까요?`,
      okText:'초기화', onOk:async()=>{
        const r=await api().save_preset({ id:p.id, name:p.name, enabled:p.enabled,
          keywords:{include:[],all:[],exclude:[]}, price_floor:0, price_ceil:0,
          cntrct_mthds:[], org_includes:[], srvce_divs:[], re_ntce_mode:'include' });
        if(r.ok){ STATE.cfg.presets=r.presets; renderPresetArea(); showSaved(); await refreshStatus(); }
        else { toast('초기화 실패', r.error,'danger'); return false; } }});
  };

  // ── 8필드 변경 → 디바운스 저장 ──
  // 키워드 3단계
  bindTags(scope);
  ['kw-include','kw-all','kw-exclude','f-org'].forEach(name=>{
    const box=$(`.tags[data-tags="${name}"]`,scope);
    if(box){ new MutationObserver(savePresetDebounced).observe(box,{childList:true});
      const inp=$('input',box); if(inp) inp.addEventListener('blur',savePresetDebounced); } });

  // 계약방법 체크
  $$('#f-cntrct .check',scope).forEach(l=>{ const inp=l.querySelector('input');
    inp.onchange=()=>{ l.classList.toggle('on',inp.checked); savePresetDebounced(); }; });

  // 추정가 하한(콤마 자동 + 한글 표시 + 저장)
  { const el=$('#f-price-floor',scope); if(el){
    const fmt=()=>{ const n=(el.value||'').replace(/[^\d]/g,''); el.value=n?(+n).toLocaleString():''; updatePriceKo('f-price-floor',n,scope); };
    fmt();
    el.addEventListener('input',fmt);
    el.addEventListener('change',()=>{ fmt(); savePresetDebounced(); }); } }

  // 용역 세부분류 체크
  $$('#f-srvce .check',scope).forEach(l=>{ const inp=l.querySelector('input');
    inp.onchange=()=>{ l.classList.toggle('on',inp.checked); savePresetDebounced(); }; });

  // 재공고 모드 라디오
  $$('#f-rentce input[name="f-rentce"]',scope).forEach(r=>r.addEventListener('change',()=>{
    if(r.checked){ $$('#f-rentce .check').forEach(l=>l.classList.toggle('on', l.querySelector('input').checked));
      savePresetDebounced(); } }));
}

/* ========== 수집 조건 마법사 ========== */

// 현재 마법사 8필드 → preset dict (savePresetDebounced/ preview_preset 공용 payload)
// 스텝마다 일부 필드만 DOM에 존재하므로, 화면에 있는 필드는 DOM값, 없으면 저장된 프리셋(activePreset)값을 사용(머지).
function collectWizardFields(){
  const p=activePreset()||{};
  const pk=(p.keywords&&!Array.isArray(p.keywords))?p.keywords
            :{include:Array.isArray(p.keywords)?p.keywords:[],all:[],exclude:[]};
  const has=sel=>!!document.querySelector(sel);
  const kwIn  = has('.tags[data-tags="kw-include"]')? readTags(document,'kw-include') : (pk.include||[]);
  const kwAll = has('.tags[data-tags="kw-all"]')?     readTags(document,'kw-all')     : (pk.all||[]);
  const kwExc = has('.tags[data-tags="kw-exclude"]')? readTags(document,'kw-exclude') : (pk.exclude||[]);
  const pflo  = has('#f-price-floor')? (parseInt(($('#f-price-floor').value||'').replace(/[^\d]/g,''))||0) : (p.price_floor||0);
  const pcei  = 0;   // 추정가격 상한(최대)은 사용하지 않음 — 하한만 운영
  const cms   = has('#f-cntrct')? $$('#f-cntrct input:checked').map(i=>i.value) : (p.cntrct_mthds||[]);
  const orgs  = has('.tags[data-tags="f-org"]')? readTags(document,'f-org') : (p.org_includes||[]);
  let sds     = has('#f-srvce')? $$('#f-srvce input:checked').map(i=>i.value) : (p.srvce_divs||[]);
  const rmode = has('#f-rentce')? (($('#f-rentce input[name="f-rentce"]:checked')?.value)||'include') : (p.re_ntce_mode||'include');
  const nm    = has('#preset-name')? ($('#preset-name').value.trim()||p.name) : p.name;
  // 용역(servc)을 안 받으면 용역 세부분류는 무의미 → 유령 데이터 방지로 비움
  const wds=(STATE.cfg&&STATE.cfg.work_divs)||[];
  if(!wds.includes('servc')) sds=[];
  return {
    id:p.id, name:nm, enabled:p.enabled,
    keywords:{ include:kwIn, all:kwAll, exclude:kwExc },
    price_floor:pflo, price_ceil:pcei, cntrct_mthds:cms,
    org_includes:orgs, srvce_divs:sds, re_ntce_mode:rmode,
  };
}

// 스텝 본문 렌더(한 시점에 한 스텝 필드만 DOM 존재 → id 충돌 없음)
function renderWizardStep(n){
  const body=$('#wiz-body'); if(!body) return;
  const c=STATE.cfg||{}; const p=activePreset()||{};
  const kw=(p.keywords&&!Array.isArray(p.keywords))?p.keywords
            :{include:Array.isArray(p.keywords)?p.keywords:[],all:[],exclude:[]};
  const checks=(id,opts,sel)=>`<div class="checks" id="${id}">${(opts||[]).map(o=>{
      const val=(typeof o==='string')?o:o.code, lab=(typeof o==='string')?o:o.label;
      const on=(sel||[]).includes(val);
      return `<label class="check ${on?'on':''}"><input type="checkbox" value="${esc(val)}" ${on?'checked':''}>${esc(lab)}</label>`;
    }).join('')}</div>`;

  if(n===1){
    body.innerHTML=`
      <div class="wizard-card view-enter">
        <div class="wizard-head">
          <svg viewBox="0 0 24 24" width="22" height="22" style="flex:0 0 auto;color:var(--primary)"><use href="#ic-search"/></svg>
          <div><h2>받고 싶은 공고의 <b>키워드</b>를 정해 주세요 <span class="badge badge--gold">수집량 결정</span></h2>
            <div class="field__help">공고 제목에 들어갈 단어로 우리 분야 공고만 선별합니다. 이 단계가 알림 양을 좌우합니다.</div></div>
        </div>
        <div class="field field--pri">
          <div class="kw-grid">
            <div class="field kw-box"><label class="field__label"><span class="kw-dot kw-dot--inc"></span>포함 <span class="kw-tag-desc">이 중 하나라도</span></label>
              ${tagInput('kw-include', kw.include, '예: 청소, 시설관리, 전기공사')}
              <div class="field__help">하나라도 공고명에 들어가면 수집합니다.</div></div>
            <div class="field kw-box"><label class="field__label"><span class="kw-dot kw-dot--all"></span>필수 <span class="kw-tag-desc">모두 들어가야</span></label>
              ${tagInput('kw-all', kw.all, '예: 용역')}
              <div class="field__help">입력한 단어가 <b>모두</b> 포함된 공고만 수집합니다.</div></div>
            <div class="field kw-box"><label class="field__label"><span class="kw-dot kw-dot--exc"></span>제외 <span class="kw-tag-desc">있으면 제외</span></label>
              ${tagInput('kw-exclude', kw.exclude, '예: 교육, 채용')}
              <div class="field__help">이 단어가 들어간 공고는 제외합니다.</div></div>
          </div>
          <div class="field__help" style="margin-top:8px">예) 포함 <b>청소·시설관리</b>, 필수 <b>용역</b>, 제외 <b>교육</b> → “청소 용역”은 받고 “청소 교육”은 버립니다. 모두 비우면 분야 전체가 옵니다.</div>
        </div>
      </div>`;
  } else if(n===2){
    body.innerHTML=`
      <div class="wizard-card view-enter">
        <div class="wizard-head">
          <svg viewBox="0 0 24 24" width="22" height="22" style="flex:0 0 auto;color:var(--primary)"><use href="#ic-settings"/></svg>
          <div><h2>어떤 종류의 사업을 받고, 우리 자격은 무엇인가요?</h2>
            <div class="field__help">큰 갈래와 회사 정보(지역·면허)는 <b>모든 수집 조건에 공통</b>으로 적용됩니다.</div></div>
        </div>
        <div class="field"><label class="field__label">업무 구분 <span class="scope-chip">📡 전역 · 모든 조건 공통</span></label>
          ${checks('f-divs', c.work_div_options, c.work_divs)}
          <div class="field__help">나라장터의 큰 분류입니다. 해당하는 항목만 선택하시면 그 분야 공고만 수집합니다.</div></div>
        <div class="field" id="wiz-srvce-wrap" style="${(c.work_divs||[]).includes('servc')?'':'display:none'}">
          <label class="field__label">용역 세부분류 <span class="muted small">(용역에만 적용 · 비우면 전체)</span></label>
          ${checks('f-srvce', c.srvce_div_options||['일반용역','기술용역'], p.srvce_divs)}
          <div class="field__help">일반=청소·경비·시설관리(노동력) / 기술=설계·감리·SW(자격·기술). 해당하는 항목만 선택하세요.</div></div>
        <div class="field"><label class="field__label">지역 <span class="scope-chip">📡 전역</span></label>
          ${regionInput(c.region||'', c.regions_available||[])}
          <div class="field__help">우리 회사 주소지입니다. “그 지역 업체만” 공고와 비교해 참여 가능 여부를 자동 판단합니다.</div></div>
        <div class="field"><label class="field__label">보유 면허·자격 <span class="scope-chip">📡 전역</span></label>
          ${licenseInput('licenses', c.licenses)}
          <div class="field__help">면허명을 검색해 선택하거나 직접 입력하세요. 비우면 ‘확인 필요’로 분류되는 공고가 늘어납니다.</div></div>
      </div>`;
  } else if(n===3){
    body.innerHTML=`
      <div class="wizard-card view-enter">
        <div class="wizard-head">
          <svg viewBox="0 0 24 24" width="22" height="22" style="flex:0 0 auto;color:var(--primary)"><use href="#ic-sliders"/></svg>
          <div><h2>더 정밀하게 좁히기 <span class="muted small">(선택)</span></h2>
            <div class="field__help">추정가격 규모·계약 방식·특정 발주처·재공고로 더 다듬을 수 있습니다. 잘 모르시면 다음 단계로 넘어가셔도 됩니다.</div></div>
        </div>
        <div class="field field--opt"><label class="field__label">받을 공고의 추정가격 하한 <span class="muted small">(이 금액 이상만 · 비우면 제한 없음)</span></label>
          <div class="price-min">
            <input class="input num" id="f-price-floor" inputmode="numeric" placeholder="예: 20,000,000" value="${p.price_floor?Number(p.price_floor).toLocaleString():''}">
            <span class="price-min__unit">원 이상</span>
            <span class="price-min__ko ${p.price_floor?'':'empty'}" id="f-price-floor-ko">${p.price_floor?wonKo(p.price_floor)+' 이상':'제한 없음'}</span>
          </div>
          <div class="field__help">설정한 금액보다 추정가격이 낮은 소액 공고는 제외됩니다. 비워 두면 금액 제한 없이 모두 수집합니다.</div></div>
        <div class="field field--opt"><label class="field__label">입찰 참여 방식 <span class="muted small">(계약방법 · 비우면 전체)</span></label>
          ${checks('f-cntrct', c.cntrct_mthd_options||['일반경쟁','제한경쟁','지명경쟁','수의계약'], p.cntrct_mthds)}
          <div class="field__help">일반=모든 업체 / 제한=자격을 갖춘 업체 / 지명=지정된 업체 / 수의=수의계약. 잘 모르시면 비워 두시면 전체가 수집됩니다.</div></div>
        <div class="field field--opt"><label class="field__label">특정 발주처가 낸 공고만 <span class="muted small">(비우면 전체 발주처)</span></label>
          ${tagInput('f-org', p.org_includes, '예: 교육청, 시청, 구청')}
          <div class="field__help">발주처 이름을 적으면 해당 발주처 공고만 수집합니다(부분일치, 여럿이면 하나라도 맞으면).</div></div>
        <div class="field field--opt"><label class="field__label">다시 올라온 공고를 받을지 <span class="muted small">(재공고)</span></label>
          <div class="checks" id="f-rentce">
            <label class="check ${(p.re_ntce_mode||'include')==='include'?'on':''}"><input type="radio" name="f-rentce" value="include" ${(p.re_ntce_mode||'include')==='include'?'checked':''}>포함</label>
            <label class="check ${p.re_ntce_mode==='exclude'?'on':''}"><input type="radio" name="f-rentce" value="exclude" ${p.re_ntce_mode==='exclude'?'checked':''}>제외</label>
            <label class="check ${p.re_ntce_mode==='only'?'on':''}"><input type="radio" name="f-rentce" value="only" ${p.re_ntce_mode==='only'?'checked':''}>재공고만</label>
          </div>
          <div class="field__help">한 번 무산되어 다시 올라온 공고입니다. 판단이 어려우시면 ‘포함’을 권장합니다.</div></div>
      </div>`;
  } else if(n===4){
    body.innerHTML=`
      <div class="wizard-card view-enter">
        <div class="wizard-head">
          <svg viewBox="0 0 24 24" width="22" height="22" style="flex:0 0 auto;color:var(--success)"><use href="#ic-check-circle"/></svg>
          <div><h2>이대로 수집을 시작할까요?</h2>
            <div class="field__help">오른쪽 미리보기에서 실제로 어떤 공고가 잡히는지 확인하세요. 언제든 ‘수집 조건’ 메뉴에서 바꿀 수 있습니다.</div></div>
        </div>
        <div class="field"><label class="field__label">이 수집 조건의 이름</label>
          <input class="input preset-name" id="preset-name" value="${esc(p.name||'')}" placeholder="예: 방사선 검사" style="max-width:420px">
          <div class="field__help">여러 분야를 받을 때 구분하기 위한 이름입니다(예: ‘방사선 검사’, ‘전기 공사’).</div></div>
        <div class="wiz-summary" id="wiz-summary"></div>
      </div>`;
    renderWizardSummary();
  }
  bindWizardStepFields(n);
  // 단계 전환 시 키보드 포커스를 새 단계의 첫 입력 요소로 이동(허공 낙하 방지)
  if(STATE.wizard._nav){ STATE.wizard._nav=false;
    const first=$('#wiz-body input, #wiz-body textarea, #wiz-body button, #wiz-body [tabindex]:not([tabindex="-1"])');
    if(first){ try{ first.focus({preventScroll:true}); }catch(e){ try{ first.focus(); }catch(_){} } } }
}

// 스텝4 자연어 요약
function renderWizardSummary(){
  const el=$('#wiz-summary'); if(!el) return;
  const f=collectWizardFields(); const c=STATE.cfg||{};
  const part=[];
  const wd=(c.work_divs||[]).map(x=>({cnstwk:'공사',servc:'용역',thng:'물품',frgcpt:'외자',etc:'기타'}[x]||x));
  if(wd.length) part.push(`<b>${wd.join('·')}</b> 분야에서`);
  if(f.keywords.all.length) part.push(`<b>${f.keywords.all.join(' ')}</b>가 반드시 있고`);
  if(f.keywords.include.length) part.push(`<b>${f.keywords.include.join('·')}</b> 중 하나가 들어가며`);
  if(f.keywords.exclude.length) part.push(`<b>${f.keywords.exclude.join('·')}</b>는 없는`);
  if(f.price_floor){ part.push(`<b>${Number(f.price_floor).toLocaleString()}원 이상</b>의`); }
  if(f.cntrct_mthds.length) part.push(`<b>${f.cntrct_mthds.join('·')}</b>이고`);
  if(f.org_includes.length) part.push(`<b>${f.org_includes.join('·')}</b>가 낸`);
  const sentence = part.length ? part.join(' ')+' 공고를 수집합니다.' : '분야 전체 공고를 수집합니다(조건 없음).';
  el.innerHTML=`<div class="preview-sum" style="margin:0"><div class="preview-sum__t">이렇게 수집합니다</div><div>${sentence}</div></div>`;
}

// 스텝별 필드 바인딩(저장 + 미리보기 병행)
function bindWizardStepFields(n){
  const scope=$('#wiz-body')||document;
  // 키워드/발주처 태그
  bindTags(scope);
  ['kw-include','kw-all','kw-exclude','f-org'].forEach(name=>{
    const box=$(`.tags[data-tags="${name}"]`,scope);
    if(box){ new MutationObserver(()=>{ savePresetDebounced(); schedulePreview(); }).observe(box,{childList:true});
      const inp=$('input',box); if(inp) inp.addEventListener('blur',()=>{ savePresetDebounced(); schedulePreview(); }); } });

  // 업무구분(전역 save_config) — 용역 체크 시 용역세부 노출 토글
  $$('#f-divs .check',scope).forEach(l=>{ const inp=l.querySelector('input');
    inp.onchange=()=>{ l.classList.toggle('on',inp.checked);
      const divs=$$('#f-divs input:checked').map(i=>i.value);
      if(divs.length){ autoSave({work_divs:divs}); STATE.cfg.work_divs=divs;
        const sw=$('#wiz-srvce-wrap'); if(sw) sw.style.display=divs.includes('servc')?'':'none';
        schedulePreview(); }
      else { inp.checked=true; l.classList.add('on'); toast('확인','업무 구분은 최소 하나가 필요합니다.','danger'); } }; });

  // 지역/면허(전역)
  bindRegion(scope, v=>{ autoSave({region:(v||'').trim()}); STATE.cfg.region=(v||'').trim(); });
  bindLicense(scope, ()=>{ const ls=readTags(document,'licenses'); autoSave({licenses:ls}); STATE.cfg.licenses=ls; });

  // 용역세부(프리셋)
  $$('#f-srvce .check',scope).forEach(l=>{ const inp=l.querySelector('input');
    inp.onchange=()=>{ l.classList.toggle('on',inp.checked); savePresetDebounced(); schedulePreview(); }; });
  // 계약방법(프리셋)
  $$('#f-cntrct .check',scope).forEach(l=>{ const inp=l.querySelector('input');
    inp.onchange=()=>{ l.classList.toggle('on',inp.checked); savePresetDebounced(); schedulePreview(); }; });
  // 추정가(프리셋)
  { const el=$('#f-price-floor',scope); if(el){
    const fmt=()=>{ const x=(el.value||'').replace(/[^\d]/g,''); el.value=x?(+x).toLocaleString():''; updatePriceKo('f-price-floor',x,scope); };
    fmt();
    el.addEventListener('input',fmt);
    el.addEventListener('change',()=>{ fmt(); savePresetDebounced(); schedulePreview(); }); } }
  // 재공고(프리셋)
  $$('#f-rentce input[name="f-rentce"]',scope).forEach(r=>r.addEventListener('change',()=>{
    if(r.checked){ $$('#f-rentce .check').forEach(l=>l.classList.toggle('on', l.querySelector('input').checked));
      savePresetDebounced(); schedulePreview(); } }));
  // 이름(스텝4)
  const nameEl=$('#preset-name',scope);
  if(nameEl) nameEl.addEventListener('change',()=>{ const v=nameEl.value.trim();
    if(v){ savePresetDebounced(); } });
}

// 스텝 전환 전 현재 입력을 즉시 저장(디바운스 플러시) → activePreset 최신화
async function wizardGoStep(n){
  clearTimeout(_presetTimer);
  await flushPresetSave();
  STATE.wizard.step=n; STATE.wizard._nav=true;   // 전환이므로 새 단계 첫 입력으로 포커스 이동
  RENDER.wizard();
}

// 마법사 네비게이션(이전/다음/건너뛰기/완료/닫기)
function bindWizardNav(){
  const W=STATE.wizard;
  const exit=$('#wiz-exit'); if(exit) exit.onclick=()=>finishWizard(false);
  const prev=$('#wiz-prev'); if(prev) prev.onclick=()=>{ if(W.step>1) wizardGoStep(W.step-1); };
  const next=$('#wiz-next'); if(next) next.onclick=()=>wizardNext();
  // 진행바의 완료·현재 단계 버튼 클릭 → 해당 단계로 이동(현재보다 뒤 단계는 비활성)
  $$('.steps .step[data-step]').forEach(b=>b.onclick=()=>{ const n=+b.dataset.step;
    if(n && n!==W.step) wizardGoStep(n); });
  // 스텝1: '이대로 시작하기' 보조 CTA / 스텝2·3: '건너뛰기'
  const mid=$('#wiz-mid'); if(mid){
    if(W.step===1) mid.innerHTML='<button class="btn btn--ghost" id="wiz-quick">이대로 시작하기</button>';
    else if(W.step===2||W.step===3) mid.innerHTML='<button class="btn btn--ghost" id="wiz-skip">건너뛰기</button>';
    else mid.innerHTML='';
    const q=$('#wiz-quick'); if(q) q.onclick=()=>finishWizard(true);
    const sk=$('#wiz-skip'); if(sk) sk.onclick=()=>{ if(W.step<4) wizardGoStep(W.step+1); };
  }
}

function wizardNext(){
  const W=STATE.wizard;
  // 스텝2: 업무구분 0개 차단(백엔드 에러 방지)
  if(W.step===2){ const divs=$$('#f-divs input:checked').map(i=>i.value);
    if(!divs.length){ toast('확인','업무 구분을 최소 하나 선택해 주세요.','danger'); return; } }
  if(W.step<4){ wizardGoStep(W.step+1); return; }
  finishWizard(true);   // 스텝4 완료
}

// 마법사 종료. complete=true 면 onboarded 저장 + 공고함으로, false 면 직접설정(filters)로.
async function finishWizard(complete){
  clearTimeout(_presetTimer);   // 잔존 디바운스 저장이 뒤늦게 발화하지 않도록
  // 진행 중 입력을 즉시 플러시(이름 포함 최신값 저장)
  try{ const payload=collectWizardFields();
    if(payload.name && payload.name.trim()){ const r=await api().save_preset(payload);
      if(r.ok){ STATE.cfg.presets=r.presets; STATE.activePreset=r.preset_id; } } }catch(e){}
  // 완료든 '건너뛰고 직접 설정'이든, 마법사를 본 이상 다음 부팅에 다시 띄우지 않는다.
  if(!STATE.cfg.onboarded){ try{ await api().save_config({onboarded:true}); STATE.cfg.onboarded=true; }catch(e){} }
  await refreshStatus();
  const wasAdd = STATE.wizard.mode==='add';
  if(complete){
    if(wasAdd){
      toast('수집 조건을 추가했습니다','조건 목록에서 확인하실 수 있습니다.','success');
      go('filters');
    } else {
      toast('수집 조건을 저장했습니다','첫 수집을 진행합니다. 잠시만 기다려 주세요.','success');
      go('status',{box:'all'});
      // 온보딩 직후 빈 공고함으로 떨어지지 않도록 첫 수집을 1회 자동 실행.
      // 라이선스·연동이 갖춰졌을 때만(아니면 백엔드가 사유 반환 → 토스트로 안내).
      setTimeout(async()=>{ try{
        const r=await api().run_collect();
        if(r && r.ok){ toast('첫 수집 완료', `참여 가능 ${r.summary?.eligible??'-'}건`, 'success'); if(CUR==='status') RENDER.status(); }
        else if(r && r.error){ toast('수집 안내', r.error, 'warning'); }
      }catch(e){} }, 400);
    }
  } else {
    go('filters');   // 건너뛰기: 직접 설정 화면으로
  }
}

/* ----- 미리보기 패널 ----- */
let _previewTimer=null;
function schedulePreview(){
  clearTimeout(_previewTimer);
  setPreviewState('pending');
  _previewTimer=setTimeout(runPreview, 400);
}
async function runPreview(){
  if(CUR!=='wizard') return;
  const payload=collectWizardFields();
  const W=STATE.wizard;
  const rid=(W.preview.lastReqId=(W.preview.lastReqId||0)+1);
  try{
    const r=await api().preview_preset(payload, 30, 3);
    if(rid!==W.preview.lastReqId) return;   // stale 응답 폐기
    if(!r.ok){ renderPreviewError(r.error); return; }
    W.preview.last=r; renderPreview(r);
  }catch(e){
    if(rid!==W.preview.lastReqId) return;
    renderPreviewError('미리보기를 불러오지 못했습니다.');
  }
}
function renderPreviewPanel(){
  const el=$('#preview-panel'); if(!el) return;
  el.innerHTML=`
    <div class="preview-head"><svg viewBox="0 0 24 24" width="18" height="18" style="color:var(--primary)"><use href="#ic-eye"/></svg> 실시간 미리보기</div>
    <div id="preview-body"><div class="preview-loading"><span class="spinner"></span> 조건에 맞는 공고를 세는 중…</div></div>`;
}
function setPreviewState(s){
  const b=$('#preview-body'); if(!b) return;
  if(s==='pending') b.innerHTML='<div class="preview-loading"><span class="spinner"></span> 조건에 맞는 공고를 세는 중…</div>';
}
function won(p){ const n=+p||0; if(n>=1e8) return (n/1e8).toFixed(1).replace(/\.0$/,'')+'억'; if(n>=1e4) return Math.round(n/1e4).toLocaleString()+'만'; return n.toLocaleString(); }
// 금액(원)을 한글로: 20000000 → "2,000만원", 150000000 → "1억 5,000만원", 0/빈값 → ''.
// 만 단위로 끊어 읽되 억/조 단위는 한글, 만 미만 자투리는 숫자로(가독성). 입력칸 아래 보조표시용.
function wonKo(p){
  let n=Math.floor(+p||0); if(n<=0) return '';
  const units=[['조',1e12],['억',1e8],['만',1e4]];
  const parts=[];
  for(const [u,base] of units){ if(n>=base){ const q=Math.floor(n/base); n-=q*base; parts.push(q.toLocaleString()+u); } }
  if(n>0) parts.push(n.toLocaleString());   // 만 미만 자투리
  return parts.join(' ')+'원';
}
// 금액 입력칸(floor/ceil) 아래 한글 보조표시 갱신. 빈값이면 안내문(미설정/제한없음).
// 추정가격 하한 입력칸 옆 한글 보조표시 갱신. 빈값이면 '제한 없음'.
function updatePriceKo(id, digits, scope=document){
  const ko=$('#'+id+'-ko', scope); if(!ko) return;
  if(digits){ ko.textContent=wonKo(digits)+' 이상'; ko.classList.remove('empty'); }
  else { ko.textContent='제한 없음'; ko.classList.add('empty'); }
}
function pvDate(s){ if(!s) return '-'; const m=String(s).match(/(\d{4})-(\d{2})-(\d{2})/); return m?`${m[2]}-${m[3]}`:String(s).slice(0,10); }
function renderPreview(r){
  const b=$('#preview-body'); if(!b) return;
  if(r.total_scanned===0 || r.total===0){ showPreviewEmpty(r); return; }
  const cards=(r.samples||[]).map(s=>{ const u=safeUrl(s.url);
    return `
    <div class="preview-card${u?' preview-card--link':''}" ${u?`data-open="${esc(u)}" role="link" tabindex="0"`:''}>
      <div class="preview-card__nm">${esc(s.name||'-')}</div>
      <div class="preview-card__org">${esc(s.instt||'-')}</div>
      <div class="preview-card__meta">${won(s.price)}원 · 마감 ${pvDate(s.clse_dt)}</div>
      <div class="preview-card__badges">
        ${s.work_div?`<span class="badge badge--neutral">${esc(s.work_div)}</span>`:''}
        ${s.cntrct_mthd?`<span class="badge badge--neutral">${esc(s.cntrct_mthd)}</span>`:''}
        ${s.re_ntce?'<span class="badge badge--warning">재공고</span>':''}
      </div></div>`; }).join('');
  // 너무 많이 잡히면 좁히도록 안내(초보가 알림 과다로 이탈하지 않게)
  const tooMany = r.total >= 60;
  b.innerHTML=`
    <div class="preview-stat"><span class="preview-stat__lead">이 조건이면</span>
      <span class="num">${r.total.toLocaleString()}</span><span class="preview-stat__unit">건</span></div>
    <div class="preview-stat__sub">최근 ${r.days}일 수집분 ${r.total_scanned.toLocaleString()}건 중</div>
    ${tooMany?'<div class="preview-warn">잡히는 공고가 많습니다. 키워드를 더 넣거나 추정가격·계약방법으로 좁히면 꼭 맞는 공고만 받으실 수 있습니다.</div>':''}
    <div class="preview-cards__cap">예시 (마감 임박순)</div>
    ${cards}
    <div class="preview-foot">입력을 멈추면 자동으로 다시 계산합니다.</div>`;
  $$('.preview-card--link',b).forEach(el=>{
    const open=()=>{ const u=el.dataset.open; if(u) api().open_external(u); };
    el.onclick=open;
    el.onkeydown=e=>{ if(e.key==='Enter'||e.key===' '){ e.preventDefault(); open(); } };
  });
}
function showPreviewEmpty(r){
  const b=$('#preview-body'); if(!b) return;
  const empty = r.total_scanned===0;
  b.innerHTML=`
    <div class="preview-stat"><span class="num" style="color:var(--text-muted)">0</span><span class="preview-stat__unit">건</span></div>
    <div class="empty" style="padding:var(--sp-4) 0">
      <div class="empty__title small">${empty?'아직 미리볼 데이터가 없습니다':'조건에 맞는 공고가 없습니다'}</div>
      <div class="empty__desc">${esc(r.note||'')}</div></div>`;
}
function renderPreviewError(msg){
  const b=$('#preview-body'); if(!b) return;
  b.innerHTML=`<div class="empty" style="padding:var(--sp-4) 0"><div class="empty__desc">${esc(msg||'미리보기 오류')}</div>
    <button class="btn btn--ghost btn--sm" onclick="runPreview()">다시 시도</button></div>`;
}

/* ---------- 테스트 발송 ---------- */
async function doTest(btn){
  const o=btn.innerHTML; btn.disabled=true; btn.innerHTML='<span class="spinner"></span> 발송 중…';
  const bot = ($('#f-bot')&&$('#f-bot').value.trim())||'';
  const chat = ($('#f-chat')&&$('#f-chat').value.trim())||'';
  try{ const r=await api().test_telegram(bot, chat);
    if(r.ok) toast('테스트 성공','텔레그램으로 테스트 메시지를 보냈습니다. 확인해 보세요.','success');
    else toast('테스트 실패', r.error,'danger');
  }catch(e){ toast('오류','발송 중 문제가 발생했습니다.','danger'); }
  finally{ btn.disabled=false; btn.innerHTML=o; }
}

