$('#nav').addEventListener('click',e=>{ const b=e.target.closest('.nav-item'); if(b) go(b.dataset.view, b.dataset.box?{box:b.dataset.box}:null); });
$('#btn-collect-top').onclick=e=>doCollect(e.currentTarget);
