/* ---------- 라이선스 게이트 ---------- */
function showLicenseGate(reason){
  const root=$('#modal-root');
  root.innerHTML=`<div class="modal-overlay" style="background:var(--bg)"><div class="modal" style="width:min(520px,92vw)">
    <div class="modal__head"><h2>라이선스 인증</h2></div>
    <div class="modal__body">
      <p style="margin-top:0">구매 시 발급받으신 라이선스 키를 입력해 주세요.</p>
      <div class="field"><input class="input" id="lic-key" placeholder="BIDRADAR.··· 형태의 키" style="font-family:var(--font-num)"></div>
      <div class="field__error" id="lic-err">${reason?esc(reason):''}</div>
      <p class="muted small" style="margin-top:14px;line-height:1.6">본 라이선스 키는 <b>구매 기관(1대 PC) 전용</b>입니다. 키의 무단 복제·공유·재배포 및 타인 양도를 금지하며, 위반 시 사전 통보 없이 이용이 정지될 수 있습니다.</p>
    </div>
    <div class="modal__foot">
      <button class="btn btn--ghost" id="lic-quit">종료하기</button>
      <button class="btn btn--ghost" id="lic-mail">문의하기</button>
      <button class="btn btn--primary" id="lic-ok">인증하기</button>
    </div></div></div>`;
  // 문의하기 → 기본 메일 클라이언트로 ai.tory.service@gmail.com 작성 창
  $('#lic-mail',root).onclick=async()=>{ const r=await api().open_external('mailto:ai.tory.service@gmail.com?subject=AI%20입찰레이더%20라이선스%20문의'); if(r&&!r.ok) $('#lic-err').textContent='메일 앱을 열지 못했습니다. ai.tory.service@gmail.com 으로 문의해 주세요.'; };
  // 종료하기 → 라이선스 미인증 시 앱 종료
  $('#lic-quit',root).onclick=()=>api().quit_app();
  const ok=$('#lic-ok'); const inp=$('#lic-key'); inp.focus();
  const submit=async()=>{ const o=ok.innerHTML; ok.disabled=true; ok.innerHTML='<span class="spinner"></span> 확인 중…';
    const r=await api().activate_license(inp.value.trim());
    ok.disabled=false; ok.innerHTML=o;
    if(r.ok){ root.innerHTML=''; toast('인증 완료', (r.org||'')+' 기관으로 인증되었습니다.','success'); await startApp(); }
    else $('#lic-err').textContent=r.error||'인증에 실패했습니다.'; };
  ok.onclick=submit; inp.addEventListener('keydown',e=>{ if(e.key==='Enter') submit(); });
}

async function startApp(){ await refreshStatus();
  // 첫 IPC 호출이 간헐적으로 cfg 를 못 받는 경우가 있어, 비었으면 짧게 한 번 더 시도(오진단 방지)
  if(!STATE.cfg){ for(let i=0;i<3 && !STATE.cfg;i++){ await new Promise(r=>setTimeout(r,250)); await refreshStatus(); } }
  // 라우팅: 연동 전 → 소개 / 연동O·마법사 미완 → 수집조건 마법사 / 둘 다 완료 → 대시보드
  const c=STATE.cfg||{};
  if(!(c.has_g2b_key && c.has_bot_token)){ go('intro'); return; }
  if(!c.onboarded){ STATE.wizard.step=1; STATE.wizard.mode='onboard'; go('wizard'); return; }
  go('dashboard'); }

(async function init(){
  await waitApi();
  try{
    const ls=await api().get_license_status();
    if(ls && ls.active){ await startApp(); }
    else { showLicenseGate(ls&&ls.reason); }
  }catch(e){ await startApp(); }
})();
